previewCss:
.darma-loader-darma-b17-blister-pack-pop { --accent: var(--loader-color, #4f46e5); --accent-2: var(--loader-secondary-color, #f8fafc); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .56); position: relative; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(2, 1fr); gap: 5%; padding: 4%; border-radius: 8px; background: color-mix(in srgb, var(--accent) 16%, transparent); box-sizing: border-box; }
.darma-loader-darma-b17-blister-pack-pop span { position: relative; border-radius: 40% / 46%; background: linear-gradient(150deg, color-mix(in srgb, #fff 45%, var(--accent-2)), var(--accent-2)); box-shadow: inset 0 -3px 0 color-mix(in srgb, #000 12%, transparent); animation: darma-loader-darma-b17-blister-pack-pop-blister-pop calc(var(--loader-speed, 1s) * 2.8) ease-in-out infinite; }
.darma-loader-darma-b17-blister-pack-pop span::after { content: ''; position: absolute; left: 26%; right: 26%; top: 38%; height: 22%; border-radius: 999px; background: var(--accent); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(2) { animation-delay: calc(var(--loader-speed, 1s) * .28); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(3) { animation-delay: calc(var(--loader-speed, 1s) * .56); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(4) { animation-delay: calc(var(--loader-speed, 1s) * .84); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(5) { animation-delay: calc(var(--loader-speed, 1s) * 1.12); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(6) { animation-delay: calc(var(--loader-speed, 1s) * 1.4); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(7) { animation-delay: calc(var(--loader-speed, 1s) * 1.68); }
.darma-loader-darma-b17-blister-pack-pop span:nth-of-type(8) { animation-delay: calc(var(--loader-speed, 1s) * 1.96); }
@keyframes darma-loader-darma-b17-blister-pack-pop-blister-pop { 0%, 10% { transform: scale(1); opacity: 1; } 18% { transform: scale(1.16); } 26%, 74% { transform: scale(.62); opacity: .3; } 88%, 100% { transform: scale(1); opacity: 1; } }

